import tempfile,os,subprocess,json
s="'use strict';
const get=async(u)=>{let r=await fetch(u,{signal:AbortSignal.timeout(5000)});if(!r.ok)throw Error('http_'+r.status);return r.json()};
function rpc(url,method,params={},limit=2200){return new Promise(resolve=>{
  let ws,done=false;const t=setTimeout(()=>end({ok:false,reason:'timeout'}),limit);
  const end=x=>{if(done)return;done=true;clearTimeout(t);try{ws?.close()}catch{}resolve(x)};
  try{ws=new WebSocket(url);ws.addEventListener('open',()=>{ws.send(JSON.stringify({id:1,method,params}))});ws.addEventListener('message',e=>{try{let a=JSON.parse(e.data);if(a.id===1)end(a.error?{ok:false,reason:a.error.message}:{ok:true,result:a.result})}catch{end({ok:false,reason:'json'})}});ws.addEventListener('error',()=>end({ok:false,reason:'ws'}))}catch{end({ok:false,reason:'construct'})}
})}
async function main(){
 const x=await get('http://127.0.0.1:17410/json/version');
 const url=x.webSocketDebuggerUrl;
 let a=await rpc(url,'SystemInfo.getProcessInfo'),b={};
 if(a.ok){await new Promise(r=>setTimeout(r,1400));b=await rpc(url,'SystemInfo.getProcessInfo')}
 const xRows=(a.result?.processInfo||[]),yRows=(b.result?.processInfo||[]);
 let ymap=new Map(yRows.map(z=>[z.id,z]));
 let all=xRows.map(z=>({id:z.id,type:z.type,cpuTime:z.cpuTime,cpuTimeDelta:ymap.has(z.id)?Number((ymap.get(z.id).cpuTime-z.cpuTime).toFixed(3)):null}));all.sort((p,q)=>(q.cpuTimeDelta||0)-(p.cpuTimeDelta||0));
 console.log(JSON.stringify({at:new Date().toISOString(),version:x.Browser,wsReadOnly:a.ok,reason:a.reason,total:all.length,renderers:all.filter(x=>x.type==='renderer').length,top:all.slice(0,18),busyRenderers:all.filter(z=>z.type==='renderer'&&z.cpuTimeDelta>0.45).length}));
}
main().catch(e=>console.log(JSON.stringify({error:e.message})));
